	inline constexpr std::array<std::array<RiteDef, 4>, 10> kRites{ {
		{ { RiteDef{ 5, 5, "The Scattered Bones", "Gather the grave-tokens round {city}", "When the Dirge first sang, Riverwood's old dead were torn from their barrow and scattered. Five grave-tokens still smoulder where they fell. Find them all and the barrow's hold on the village weakens.", "", "", "", 0.0f }, RiteDef{ 0, 25, "Blood on the River", "Slay the risen within {city}", "Now the dead come looking for what you took. Put {n} of them back in the ground before they reach the mill.", "", "", "", 0.0f }, RiteDef{ 6, 90, "The Barrow Rite", "Keep the dead out of the ritual circle", "The shrine's circle can bind the barrow shut, but only if no dead thing crosses it while it burns. Keep them out for {n} seconds. If they swarm it, the circle breaks and the rite begins again.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Barrow-Lord", "Slay Hrothgar the Barrow-Lord", "Bound out of his barrow, the Barrow-Lord walks Riverwood himself. Find Hrothgar in the night and end him.", "", "king", "Hrothgar the Barrow-Lord", 25.0f } } },
		{ { RiteDef{ 1, 4, "Kyne's Watchfires", "Light the four watchfires", "Four watchfires once burned for Kyne round the Plains District. Stand by each until it catches, and keep the dead off you while it does.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Ash-Skald", "Hunt down the Ash-Skald", "A dead bard of Jorrvaskr sings the Dirge in the streets, and the dead dance to it. Hunt the Ash-Skald down before dawn.", "", "knight", "The Ash-Skald", 18.0f }, RiteDef{ 7, 4, "The Sun's Road", "Kindle the braziers as the sun travels", "Kyne's priests lit their fires the way the sun walks: first where it rises in the EAST, then SOUTH at noon, then WEST where it sets, and NORTH last in the dark. Light them out of order and the dead will answer.", "ESWN", "", "", 0.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "Its root cracked, the Dirge calls its Herald: Grimmvar, the Undying Wyrm, who walks only in fog. The next night you face in {city}, the fog will roll in. Slay it before dawn and the city is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 0, 30, "The Hangman's Dead", "Slay the risen within {city}", "Everyone who swung from Solitude's gallows has climbed back down. Put {n} of them in the ground for good.", "", "", "", 0.0f }, RiteDef{ 5, 6, "Bones of the Wolf Queen", "Recover the Wolf Queen's bones", "Potema's bones were scattered so she could never rise again. The Dirge is gathering them. Find the six pieces before it does.", "", "", "", 0.0f }, RiteDef{ 4, 1, "Potema's Last Thrall", "Destroy Potema's Last Thrall", "Her last thrall still serves her and raises the dead in her name. Destroy it.", "", "lich", "Potema's Last Thrall", 22.0f }, RiteDef{ 6, 120, "The Queen's Requiem", "Keep the dead out of the requiem circle", "Sing her down. The priests' circle at your shrine must burn for {n} seconds with no dead inside it. If they break it, it starts again.", "", "", "", 0.0f } } },
		{ { RiteDef{ 7, 4, "The Five Hundred's Fires", "Kindle the braziers in Ysgramor's order", "Ysgramor's companions lit their fires from the sea: NORTH where the ships came in, then EAST, then SOUTH, then WEST. Keep their order or the dead come.", "NESW", "", "", 0.0f }, RiteDef{ 0, 30, "The Grey Quarter's Dead", "Slay the risen within {city}", "The dead are thick in the narrow streets. Slay {n} of them.", "", "", "", 0.0f }, RiteDef{ 2, 120, "Stand at Ysgramor's Shrine", "Hold the shrine of {city}", "Stand your ground at the shrine while the night throws everything at you. Hold it for {n} seconds.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Frost-Jarl", "Slay the Frost-Jarl Hrolvar", "A jarl of the old Kings walks again, frozen and furious. Find Hrolvar in the night and break him.", "", "king", "Frost-Jarl Hrolvar", 30.0f } } },
		{ { RiteDef{ 5, 5, "The Tonal Keys", "Find the Dwemer tonal keys", "Five Dwemer tonal keys lie about the city. Together they can tune the old resonator against the Dirge. Find them.", "", "", "", 0.0f }, RiteDef{ 6, 100, "The Tonal Resonator", "Keep the dead out of the resonator's circle", "The resonator hums at your shrine. Keep the dead out of its circle for {n} seconds while it tunes the stone against the Dirge.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Witch-Bones", "Destroy the Forsworn Witch-Bones", "A briarheart witch, long dead, raises the Reach's dead against the city. Destroy her.", "", "wailer", "The Forsworn Witch-Bones", 22.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "The Dirge sends its Herald, Grimmvar, out of the fog. Slay it before dawn and Markarth is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 0, 25, "Rats in the Ratway", "Slay the risen within {city}", "The canals give up their drowned. Put {n} of them back under.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Nightingale's Shade", "Hunt the Nightingale's Shade", "A dead Nightingale hunts the rooftops, quick and silent. Catch it before dawn.", "", "runner", "The Nightingale's Shade", 20.0f }, RiteDef{ 5, 6, "Nocturnal's Keys", "Find Nocturnal's keys", "Six of Nocturnal's black keys are hidden round the city. Gather them and the shadows will stop hiding the dead.", "", "", "", 0.0f }, RiteDef{ 2, 150, "The Long Night", "Hold the shrine of {city}", "Hold the shrine through the worst of the night: {n} seconds, no retreat.", "", "", "", 0.0f } } },
		{ { RiteDef{ 1, 5, "Arkay's Grave-Candles", "Light the five grave-candles", "Five grave-candles stand round the shrine, one for each of Arkay's mercies. Light them all.", "", "", "", 0.0f }, RiteDef{ 5, 6, "The Restless Graves", "Lay the restless grave-markers", "Falkreath's graveyard is torn open. Six grave-markers have been flung across the town. Find them.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Tolling Order", "Kindle the braziers in the tolling order", "Arkay's bell tolls SOUTH to the graves, then WEST, then NORTH, then EAST. Light the braziers in that order or the dead will rise to the wrong toll.", "SWNE", "", "", 0.0f }, RiteDef{ 4, 1, "The Gravewarden", "Slay the Gravewarden", "The Gravewarden guarded Falkreath's dead for a thousand years. Now he leads them. Lay him to rest.", "", "knight", "The Gravewarden", 28.0f } } },
		{ { RiteDef{ 6, 90, "The Marsh Vigil", "Keep the dead out of the vigil circle", "Keep the vigil at your shrine: {n} seconds with no dead inside the circle, or it starts again.", "", "", "", 0.0f }, RiteDef{ 0, 30, "Drowned Dead", "Slay the risen within {city}", "The marsh dead crawl up out of the bog. Put {n} of them down.", "", "", "", 0.0f }, RiteDef{ 4, 1, "Movarth's Blood-Thrall", "Destroy Movarth's Blood-Thrall", "A thrall of the old vampire lord leads the marsh dead. Destroy it.", "", "bloater", "Movarth's Blood-Thrall", 22.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "Morthal's fog is thick enough for the Herald to walk in. Slay Grimmvar before dawn and Morthal is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 5, 5, "Shards of the Nightmare", "Gather the nightmare shards", "Five shards of a broken dream-skull feed the town's nightmares, and the nightmares feed the Dirge. Gather them.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Dreamer's Path", "Kindle the braziers along the dreamer's path", "The dreamer walks WEST to sleep, NORTH into the dream, EAST to the nightmare and SOUTH to wake. Light the braziers in that order.", "WNES", "", "", 0.0f }, RiteDef{ 4, 1, "Vaermina's Hound", "Hunt Vaermina's Hound", "A hound of the Daedric dream stalks Dawnstar's dead. Hunt it down.", "", "bloater", "Vaermina's Hound", 22.0f }, RiteDef{ 6, 130, "Wake the Town", "Keep the dead out of the waking circle", "Wake Dawnstar from its nightmare: keep the dead out of the circle at your shrine for {n} seconds.", "", "", "", 0.0f } } },
		{ { RiteDef{ 1, 4, "The Magnus Lights", "Light the four Magnus lights", "Four lights of Magnus burn against the dark round your shrine. Kindle them.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Drowned Archmage", "Destroy the Drowned Archmage", "An archmage lost in the Great Collapse walks out of the sea. Destroy what is left of him.", "", "lich", "The Drowned Archmage", 24.0f }, RiteDef{ 5, 6, "Lost Pages of the College", "Recover the College's lost pages", "Six pages of a warding scroll were lost when the city fell into the sea. Find them in the snow.", "", "", "", 0.0f }, RiteDef{ 2, 150, "The Last Stand of Winterhold", "Hold the shrine of {city}", "Winterhold has fallen once. Not again. Hold the shrine for {n} seconds.", "", "", "", 0.0f } } },
	} };
